'use strict';
const $=id=>document.getElementById(id);
const labels=['Đời sống','Sản xuất','Công bằng','Ngân sách'];
const icons=['<circle cx="12" cy="7" r="3"/><path d="M5 22v-6a7 7 0 0 1 14 0v6M9 22v-5m6 5v-5"/>','<path d="M3 22V10l6 3V8l6 4V3h4v19ZM7 17v2m5-2v2m5-2v2"/>','<path d="M12 3v19M4 7h16M7 7 3 16h8L7 7Zm10 0-4 9h8l-4-9ZM7 22h10"/>','<path d="m3 8 9-5 9 5H3Zm1 13h16M6 11v7m6-7v7m6-7v7"/>'];
const people=[['Hội đồng Lao động','Tiền lương và việc làm','LAO ĐỘNG','#bb7758'],['Hội đồng Công nghiệp','Nhà máy và đầu tư','CÔNG NGHIỆP','#648575'],['Hội đồng Xã hội','An sinh và dịch vụ thiết yếu','AN SINH','#a89661'],['Hội đồng Kinh tế','Ngân sách và giá cả','VĨ MÔ','#778b9b'],['Hội đồng Nhân lực','Học nghề và cơ hội mới','NHÂN LỰC','#af8272'],['Hội đồng Phát triển vùng','Nông nghiệp, hạ tầng và môi trường','PHÁT TRIỂN VÙNG','#8c9260']];
// Effects are illustrative index changes, not calibrated economic estimates.
const option=(text,effect,why,delayed,policy)=>({text,effect,why,delayed,policy});
const event=(p,title,q,...options)=>({p,title,q,options});
const later=(delay,effect,title,text)=>({delay,effect,title,text});
const cards=simplifyDecisions(buildPolicies({event,option,later}),option);
let state,locked=false;
const fresh=()=>({turn:0,stats:[60,60,55,65],lastDelta:[0,0,0,0],policies:[],pending:[],history:[],crisis:[0,0,0,0],ended:false,support:groups.map(()=>58),lastReactions:null,unrest:0,endReason:null,aiReport:null});
// Version 3 saves predate interest groups; fresh() fills the missing fields.
try{state=JSON.parse(localStorage.getItem('thecan-buttons-v3'));if(!state||![3,4].includes(state.version)||!Array.isArray(state.stats)||state.turn<0||state.turn>30)state=fresh();else{state={...fresh(),...state};if(!Array.isArray(state.support)||state.support.length!==groups.length)state.support=groups.map(()=>58)}}catch{state=fresh()}
function save(){try{localStorage.setItem('thecan-buttons-v3',JSON.stringify({...state,version:4}))}catch{}}
// Popular unrest ends the term only after the first year.
const UNREST_LEVEL=40,GRACE_TURNS=3;
function endReason(){return state.endReason||(state.turn>=30?'term':'crisis')}
function stanceClass(level){return level>=3?'up':level<=1?'down':'neutral'}
function stanceSummary(reactions){if(!reactions)return '';const pick=f=>groups.filter((g,i)=>f(stanceLevel(reactions[i]))).map(g=>g.name).join(', ');const pro=pick(l=>l>=3),con=pick(l=>l<=1);return [pro&&'Ủng hộ: '+pro,con&&'Phản đối: '+con].filter(Boolean).join(' · ')}
function renderGroups(){const r=state.lastReactions,pop=popularSupport(state.support);$('groups').innerHTML=groups.map((g,i)=>{const level=r?stanceLevel(r[i]):null,quote=r?g.quotes[level][state.turn%2]:'';return `<li><div class="group-head"><b>${g.name}</b>${r?`<span class="stance ${stanceClass(level)}">${stances[level]}</span>`:''}</div>${r?`<p>“${quote}”</p>`:`<p class="group-role">${g.role}</p>`}<div class="support" title="Mức ủng hộ của ${g.name}: ${state.support[i]} trên 100"><div class="meter-line" role="meter" aria-label="Mức ủng hộ của ${g.name}" aria-valuenow="${state.support[i]}" aria-valuemin="0" aria-valuemax="100"><span style="width:${state.support[i]}%"></span></div><small>${state.support[i]}</small></div></li>`}).join('');$('groups-note').textContent=r?'Phản ứng với quyết định vừa chọn.':'Các nhóm sẽ phản ứng sau mỗi quyết định của bạn.';$('popular').innerHTML=`Lòng dân <strong class="${pop<=UNREST_LEVEL+10?'warn':''}">${pop}/100</strong>`}
function portrait(p){const color=people[p][3];return `<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M11 102c0-24 15-36 39-36s39 12 39 36" fill="${color}"/><path d="m37 68 13 18 13-18" fill="#f4e7cd"/><path d="M42 56h16v18H42" fill="#c68f6e"/><ellipse cx="50" cy="42" rx="22" ry="26" fill="#dba880"/><path d="M28 42V28c0-21 44-22 44 1v12l-8-19c-10 8-23 9-33 7Z" fill="#343e32"/><path d="M40 44h2m16 0h2" stroke="#343e32" stroke-width="3" stroke-linecap="round"/><path d="M45 56q5 4 10 0" fill="none" stroke="#8d5743" stroke-width="2"/>${p===1||p===4?'<path d="M34 40h13v10H34Zm19 0h13v10H53Zm-6 3h6" fill="none" stroke="#344739" stroke-width="2"/>':''}${p===5?'<path d="M13 30 50 6l37 24Z" fill="#c9b279"/>':''}</svg>`}
function historyWhy(h){if(h.kind==='annual')return 'Nguồn thu, nhu cầu xã hội và các chính sách dài hạn cùng tác động đến nền kinh tế.';if(h.kind==='policy'||h.kind==='later')return '';return (h.why||'').split(' Tác động tức thời:')[0]}
function effectText(e){return e.map((v,i)=>v?labels[i]+' '+(v>0?'+':'')+v:null).filter(Boolean).join(' · ')}
function meterDelta(i){if(!state.turn)return '';const n=state.lastDelta?.[i]||0;return '<span class="meter-delta '+(n>0?'up':n<0?'down':'neutral')+'" title="Thay đổi thực tế của lượt vừa rồi, gồm quyết định và các hệ quả đến hạn" aria-label="'+(n>0?'Tăng ':n<0?'Giảm ':'Không đổi ')+Math.abs(n)+' so với trước lượt">'+(n>=0?'+':'−')+Math.abs(n)+'</span>'}
function render(){const c=cards[Math.min(state.turn,29)],p=people[c.p];$('meters').innerHTML=labels.map((l,i)=>`<div class="meter ${state.stats[i]<25?'low':''}" title="${l}: ${state.stats[i]} trên 100"><svg viewBox="0 0 24 26" aria-hidden="true">${icons[i]}</svg>${l}<div class="meter-line" role="meter" aria-label="${l}" aria-valuenow="${state.stats[i]}" aria-valuemin="0" aria-valuemax="100"><span style="width:${state.stats[i]}%"></span></div><strong>${state.stats[i]} ${meterDelta(i)}</strong></div>`).join('');$('turn').textContent=`Quyết định ${String(Math.min(state.turn+1,30)).padStart(2,'0')} / 30`;$('year').textContent=`Năm ${Math.min(10,Math.floor(state.turn/3)+1)} · ${state.turn<10?'Xây nền':state.turn<20?'Thử thách':'Giữ thế cân'}`;$('dots').innerHTML=Array.from({length:10},(_,i)=>`<i class="${i<=Math.floor(state.turn/3)?'on':''}"></i>`).join('');$('category').textContent=p[2];$('card-num').textContent=`${String(Math.min(state.turn+1,30)).padStart(2,'0')}`;$('portrait').innerHTML=portrait(c.p);$('name').textContent=p[0];$('role').textContent=p[1];$('title').textContent=c.title;$('question').textContent='“'+c.q+'”';$('choices').innerHTML=c.options.map((o,i)=>'<button type="button" data-choice="'+i+'" '+(state.ended?'disabled':'')+'><span class="option-letter" aria-hidden="true">'+String.fromCharCode(65+i)+'</span><span>'+o.text+'</span>'+(o.policy?'<small>Ảnh hưởng kéo dài '+o.policy.years+' năm</small>':'')+'</button>').join('');$('policy-list').innerHTML=state.policies.length?state.policies.map(p=>'<li><b>'+p.name+'</b><span>'+'Ảnh hưởng kéo dài '+p.years+' năm nữa'+'</span></li>').join(''):'<li>Chưa có định hướng nhiều năm.</li>';
$('pending-count').textContent=state.pending.length+' hệ quả đang chờ';
$('log-count').textContent=`${state.turn} quyết định`;$('log').innerHTML=state.history.length?state.history.slice().reverse().map(h=>`<li><b>${h.kind==='later'?'HỆ QUẢ TRỞ LẠI':h.kind==='annual'?'QUYẾT TOÁN NĂM':h.kind==='policy'?'ĐỊNH HƯỚNG NHIỀU NĂM':`QUYẾT ĐỊNH ${String(h.turn).padStart(2,'0')}`} · ${h.title}</b>${h.text}<p>${historyWhy(h)}</p>${h.reactions?`<p class="log-groups">${stanceSummary(h.reactions)||'Các nhóm còn dè dặt.'}</p>`:''}</li>`).join(''):'<li class="empty">Trang đầu còn trống.<br>Hãy viết bằng lựa chọn của bạn.</li>';renderGroups();renderTalk();$('resign').disabled=state.ended||!state.turn;document.querySelector('.game').classList.toggle('finished',state.ended);placeGroups()}
function placeGroups(){const r=document.querySelector('.reactions'),intro=document.querySelector('.intro'),side=state.turn>0&&matchMedia('(min-width:851px)').matches;if(side&&r.parentNode!==intro)intro.appendChild(r);else if(!side&&r.parentNode===intro)$('feedback').after(r);intro.classList.toggle('playing',side)}
matchMedia('(min-width:851px)').addEventListener('change',placeGroups);
function apply(effect){state.stats=state.stats.map((v,i)=>Math.max(0,Math.min(100,v+effect[i])))}
function choose(i){
if(locked||state.ended||$('info').open||$('ending').open||!Number.isInteger(i)||i<0||i>=cards[state.turn].options.length)return;
locked=true;const before=[...state.stats],c=cards[state.turn],o=c.options[i],reactions=groupReactions(o);
$('card').style.transform='translateY(-6px)';$('card').style.opacity='0';
apply(o.effect);state.turn++;
state.history.push({turn:state.turn,title:c.title,text:o.text,why:o.why,reactions});
if(o.policy)state.policies.push({...o.policy});
if(o.delayed)state.pending.push({...o.delayed,due:state.turn+o.delayed.delay});
let feedback=o.why;
if(state.turn%3===0){
const revenue=7+Math.floor(state.stats[1]/20);apply([-5,-4,-4,revenue]);
state.history.push({kind:'annual',title:'Ngân sách và nhu cầu hằng năm',text:'Khép lại năm '+state.turn/3,why:'Nguồn thu phụ thuộc năng lực sản xuất; nhu cầu xã hội và hao mòn tạo sức ép.'});
state.policies=state.policies.filter(p=>{apply(p.effect);p.years--;state.history.push({kind:'policy',title:p.name,text:p.years?'Định hướng tiếp tục có hiệu lực.':'Đã hết chu kỳ ba năm.',why:''});return p.years>0});
feedback+=' Đã quyết toán năm: nguồn thu, nhu cầu mới và các định hướng nhiều năm cùng có tác động.';
}
state.pending=state.pending.filter(e=>{if(e.due>state.turn)return true;apply(e.effect);state.history.push({kind:'later',title:e.title,text:e.text,why:''});feedback+=' '+e.text;return false});
state.lastDelta=state.stats.map((v,j)=>v-before[j]);
state.support=updateSupport(state.support,reactions,state.stats);state.lastReactions=reactions;
state.crisis=state.crisis.map((v,j)=>state.stats[j]<=10?v+1:0);state.unrest=state.turn>GRACE_TURNS&&popularSupport(state.support)<=UNREST_LEVEL?state.unrest+1:0;
state.endReason=state.crisis.some(v=>v>=2)?'crisis':state.unrest>=2?'overthrow':state.turn>=30?'term':null;state.ended=!!state.endReason;save();
setTimeout(()=>{render();$('title').focus?.({preventScroll:true});$('feedback').textContent=feedback;$('card').style.transform='';$('card').style.opacity='1';locked=false;if(state.ended)showEnding()},180)
}
function band(v,texts){return texts[v>=65?0:v>=40?1:v>=20?2:3]}
function countryReport(){const s=state.stats,sup=state.support,pop=popularSupport(sup),order=groups.map((g,i)=>i).sort((a,b)=>sup[b]-sup[a]),top=order[0],bottom=order[order.length-1];
const economy=band(s[1],['Nhà máy chạy gần hết công suất; đầu tư và việc làm mới tiếp tục mở ra.','Sản xuất giữ được nhịp nhưng chưa có cú bứt phá.','Nhiều cơ sở thu hẹp, đơn hàng thưa dần và việc làm mới khan hiếm.','Sản xuất đình đốn; vốn và lao động rời khỏi các ngành chủ lực.'])+' '+band(s[3],['Ngân sách dư dả, đủ sức chống đỡ cú sốc tiếp theo.','Ngân sách cân đối được nhưng ít dư địa.','Ngân sách căng thẳng; nhiều khoản chi phải hoãn lại.','Ngân sách cạn kiệt; các cam kết công khó được duy trì.']);
const society=band(s[0],['Phần lớn gia đình yên tâm về thu nhập, chỗ ở và khám chữa bệnh.','Đời sống tạm ổn, nhưng nhiều hộ vẫn chật vật trước giá cả.','Giá cả và việc làm bấp bênh khiến nhiều gia đình phải thắt lưng buộc bụng.','Nhu cầu thiết yếu của nhiều người không được đáp ứng.'])+' '+band(s[2],['Khoảng cách giàu nghèo thu hẹp; trẻ em vùng xa có cơ hội gần với thành phố.','Cơ hội được mở rộng từng phần; khoảng cách giữa các vùng vẫn còn.','Thành quả tập trung ở một số nhóm; vùng xa và người thu nhập thấp tụt lại.','Bất bình đẳng sâu sắc; niềm tin vào sự công bằng suy giảm.']);
const politics=(sup[top]-sup[bottom]<8?'Các nhóm lợi ích có thái độ khá gần nhau.':`Chỗ dựa vững nhất là ${groups[top].name} (${supportWord(sup[top])}); ${groups[bottom].name} là nhóm ${supportWord(sup[bottom])} nhất.`)+' '+(pop>=60?'Lòng dân nhìn chung ủng hộ đường lối đã chọn.':pop>=40?'Lòng dân chia rẽ: mỗi quyết định đều có người được, người mất.':pop>UNREST_LEVEL?'Bất bình âm ỉ lan trong nhiều tầng lớp.':'Bất bình đã thành làn sóng phản đối rộng khắp.');
let disputed=null,spread=-1;state.history.forEach(h=>{if(!h.reactions)return;const d=Math.max(...h.reactions)-Math.min(...h.reactions);if(d>spread){spread=d;disputed=h}});
let contested='';if(disputed&&spread>=3){const pro=groups.filter((g,i)=>stanceLevel(disputed.reactions[i])>=3).map(g=>g.name),con=groups.filter((g,i)=>stanceLevel(disputed.reactions[i])<=1).map(g=>g.name);contested=`Quyết định gây tranh cãi nhất: “${disputed.text}” (${disputed.title}).`+(pro.length?` ${pro.join(', ')} ủng hộ`:'')+(pro.length&&con.length?';':'')+(con.length?` ${con.join(', ')} phản đối`:'')+'.'}
const legacy=state.policies.length?`Định hướng còn hiệu lực: ${state.policies.map(p=>p.name).join('; ')}.`:'';const later=state.pending.length?` ${state.pending.length} hệ quả vẫn đang chờ đến hạn.`:'';
return {pop,contested,html:`<h3>Tình hình đất nước</h3><p><b>Kinh tế.</b> ${economy}</p><p><b>Xã hội.</b> ${society}</p><p><b>Chính trị.</b> ${politics}</p>${contested?`<p>${contested}</p>`:''}${legacy||later?`<p><b>Di sản để lại.</b> ${legacy}${later}</p>`:''}<div class="result-grid groups-grid">${groups.map((g,i)=>`<div>${g.name}<strong>${sup[i]}</strong><small>${supportWord(sup[i])}</small></div>`).join('')}</div>`}}
function showEnding(){const s=state.stats,reason=endReason(),years=Math.ceil(state.turn/3),report=countryReport();
let title=reason==='crisis'?'Thế cân đứt gãy':reason==='overthrow'?'Mất lòng dân':reason==='resign'?'Rời ghế giữa chừng':Math.min(...s)>=35?'Thịnh vượng được chia sẻ':s[1]<35?'Sẻ chia cần nguồn lực':s[2]<35||s[0]<35?'Tăng trưởng thiếu sẻ chia':'Nguồn lực đang mỏng';
const crisisIndex=state.crisis.findIndex(v=>v>=2);
let p=reason==='crisis'?`${labels[crisisIndex<0?0:crisisIndex]} ở ngưỡng khủng hoảng trong hai lượt liên tiếp. Những nhu cầu không được giải quyết đã tích tụ thành điểm gãy.`:reason==='overthrow'?`Sau ${state.turn} quyết định, lòng dân xuống còn ${report.pop}/100 trong hai lượt liên tiếp. Kiến nghị và biểu tình lan rộng; nhiệm kỳ của bạn kết thúc sớm.`:reason==='resign'?`Bạn từ chức sau ${state.turn} quyết định, ở năm thứ ${years} của nhiệm kỳ. Người kế nhiệm tiếp quản đất nước trong tình trạng dưới đây.`:'Bạn đã đi hết 10 năm. Một nhiệm kỳ được đánh giá bằng cả đời sống, cơ hội, năng lực sản xuất, nguồn lực công và lòng dân.';
let advice=reason==='overthrow'?'Cần lắng nghe các nhóm đông dân nhất: người làm công, nông dân và trí thức.':s[0]<35?'Cần ưu tiên nhu cầu thiết yếu và chất lượng việc làm.':s[1]<35?'Cần khôi phục đầu tư, kỹ năng và khả năng tạo ra của cải.':s[2]<35?'Cần mở rộng cơ hội và giúp thành quả đến với nhóm ít được hưởng lợi.':s[3]<35?'Cần củng cố nguồn thu và lựa chọn chi tiêu để duy trì các cam kết.':'Bạn đã giữ được nền tảng ở cả bốn mặt. Hãy thử nhiệm kỳ khác để xem các ưu tiên thay đổi kết quả ra sao.';
$('ending-body').innerHTML=`<h2>${title}</h2><p>${p}</p><div class="result-grid">${labels.map((l,i)=>`<div>${l}<strong>${s[i]}/100</strong></div>`).join('')}</div>${report.html}${AI_ENDPOINT?aiReportSection():''}<p>${advice}</p><h3>Vậy chiếc bánh nên chia thế nào?</h3><p>Gắn phần hưởng với đóng góp và hiệu quả để duy trì động lực; dùng thuế, dịch vụ công và an sinh để bảo đảm nhu cầu thiết yếu và cơ hội. Đồng thời giữ nguồn lực cho sản xuất ngày mai.</p><p class="small">Chỉ số, nhóm lợi ích và phản ứng là giả định minh họa, không phải số liệu, khảo sát hay dự báo về Việt Nam. Giá trị thặng dư không đồng nhất với lợi nhuận kế toán. ${(state.pending.length||state.policies.length)?'Một số hệ quả hoặc định hướng vẫn còn hiệu lực sau nhiệm kỳ; báo cáo chưa phản ánh hết tác động dài hạn.':''}</p>`;if(!$('ending').open)$('ending').showModal();requestAiReport(report.contested)}
function resign(){if(state.ended||!state.turn||locked)return;$('info-body').innerHTML='<h2>Từ chức?</h2><p>Nhiệm kỳ sẽ kết thúc ngay và bạn nhận báo cáo tình hình đất nước lúc này. Bạn có thể đóng cửa sổ này để tiếp tục điều hành.</p><button class="primary" id="confirm-resign">Từ chức</button>';$('info').showModal();$('confirm-resign').onclick=confirmResign}
function confirmResign(){if(state.ended||!state.turn)return;state.endReason='resign';state.ended=true;save();$('info').close();render();$('feedback').textContent='Bạn đã từ chức.';showEnding()}
function restart(){if(state.turn&&!state.ended){$('info-body').innerHTML='<h2>Bắt đầu một nhiệm kỳ mới?</h2><p>Tiến trình hiện tại sẽ được thay thế. Bạn có thể đóng cửa sổ này để tiếp tục.</p><button class="primary" id="confirm-reset">Bắt đầu lại</button>';$('info').showModal();$('confirm-reset').onclick=reset}else reset()}
function reset(){state=fresh();reportRequest=null;save();locked=false;$('ending').close();$('info').close();render();$('feedback').textContent='Nhiệm kỳ vĩ mô mới. Bạn sẽ chọn hướng phát triển nào?'}
function info(theory=false){$('info-body').innerHTML=theory?'<h2>Đằng sau mỗi quyết định</h2><h3>Sản xuất và trao đổi</h3><p>Hàng hóa có giá trị sử dụng và giá trị. Hàng làm ra chưa bán được khiến vốn mắc ở khâu lưu thông; năng suất, nhu cầu và cạnh tranh ảnh hưởng kết quả sản xuất.</p><h3>Lao động và thành quả</h3><p>Trong lý luận của C. Mác, tư bản bất biến chuyển giá trị vào sản phẩm; lao động sống tạo giá trị mới, gồm phần bù đắp giá trị sức lao động và giá trị thặng dư. Không đồng nhất giá trị thặng dư với số tiền lãi trên báo cáo kế toán.</p><h3>Phân phối và phân phối lại</h3><p>Tiền lương, phần thu nhập từ vốn và các nguồn lực khác hình thành trong hoạt động kinh tế; thuế và chi tiêu công tiếp tục phân phối lại. Công bằng còn là khả năng tiếp cận giáo dục, y tế và việc làm.</p><p class="small">Game dùng các quan hệ đơn giản hóa để gợi thảo luận. Điểm số không chứng minh một chính sách luôn đúng. Các nhân vật và tình huống đều hư cấu.</p>':'<h2>Giữ thế cân.</h2><p>Bạn có <b>30 quyết định trong 10 năm</b> để điều hành chính sách ở tầm quốc gia trong một Việt Nam giả lập. Bạn quyết định luật chơi và phân bổ nguồn lực, thay vì quản lý từng doanh nghiệp.</p><ul><li>Mỗi câu có 2–4 lựa chọn. Bấm vào phương án bạn muốn; hoặc dùng Tab để di chuyển và Enter hay phím cách để chọn.</li><li>Hãy cân nhắc nội dung và hoàn cảnh của từng quyết định. Game không tiết lộ trước mức thay đổi. Sau mỗi lượt, số cộng/trừ cạnh thanh phía trên cho biết thay đổi thực tế, gồm quyết định vừa chọn và các hệ quả đến hạn.</li><li>Chính sách nhiều năm chỉ ghi thời gian ảnh hưởng. Tác động tiếp tục qua các năm; đầu tư và khủng hoảng còn có hệ quả xuất hiện sau nhiều lượt.</li><li>Sau mỗi quyết định, năm nhóm lợi ích cho biết họ ủng hộ hay phản đối. Mức ủng hộ của họ tích lũy qua các lượt.</li><li>Nhiệm kỳ kết thúc sớm khi một chỉ số ≤10 trong hai lượt liên tiếp, hoặc khi lòng dân ≤40 trong hai lượt liên tiếp (tính từ năm thứ hai). Chỉ số cao không làm bạn thua. Bạn cũng có thể từ chức bất cứ lúc nào.</li><li>Khi nhiệm kỳ kết thúc, báo cáo mô tả tình hình kinh tế, xã hội và chính trị của đất nước lúc đó.</li><li>Tiến trình tự lưu trên trình duyệt. Bạn có thể chơi lại để so sánh.</li></ul><p class="small">Mô hình học tập giả định. Không có phương án tốt cho mọi hoàn cảnh.</p>';$('info').showModal()}
$('choices').addEventListener('click',e=>{const button=e.target.closest('button[data-choice]');if(button)choose(Number(button.dataset.choice))});$('help').onclick=()=>info();$('theory').onclick=()=>info(true);document.querySelector('.close').onclick=()=>$('info').close();$('restart').onclick=restart;$('resign').onclick=resign;$('talk-groups').onclick=e=>{const b=e.target.closest('button[data-group]');if(b)pickGroup(Number(b.dataset.group))};$('talk-form').onsubmit=e=>{e.preventDefault();askGroup($('talk-input').value)};$('again').onclick=reset;$('review').onclick=()=>$('ending').close();render();if(state.ended)showEnding();

